**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    vector<int> liczby;
    vector<int> maxCzynniki;
    vector<vector<int>> rozklady;

    while (plik >> liczba) {
        liczby.push_back(liczba);
        int n = liczba;
        vector<int> czynniki;
        for (int d = 2; d * d <= n; d++) {
            while (n % d == 0) {
                czynniki.push_back(d);
                n /= d;
            }
        }
        if (n > 1) czynniki.push_back(n);
        rozklady.push_back(czynniki);
        maxCzynniki.push_back(czynniki.back());
    }

    cout << "a) Rozklady i najwieksze czynniki:" << endl;
    for (int i = 0; i < (int)liczby.size(); i++) {
        cout << liczby[i] << " = ";
        for (int j = 0; j < (int)rozklady[i].size(); j++) {
            if (j > 0) cout << " * ";
            cout << rozklady[i][j];
        }
        cout << " -> max czynnik: " << maxCzynniki[i] << endl;
    }

    cout << endl << "b) Najgladsza liczba: ";
    int minIdx = 0;
    for (int i = 1; i < (int)liczby.size(); i++) {
        if (maxCzynniki[i] < maxCzynniki[minIdx]) minIdx = i;
    }
    cout << liczby[minIdx] << " (max czynnik: " << maxCzynniki[minIdx] << ")" << endl;

    cout << endl << "c) Liczby z max czynnikiem > 10: ";
    int ile = 0;
    for (int i = 0; i < (int)liczby.size(); i++) {
        if (maxCzynniki[i] > 10) ile++;
    }
    cout << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Rozklad na czynniki pierwsze: dzielimy przez d=2,3,4,..., dopoki d*d <= n. Jesli po petli n > 1, to n jest czynnikiem pierwszym. Ostatni czynnik w wektorze jest najwiekszy (bo dzielimy od najmniejszych). "Gladka" liczba to taka, ktorej najwiekszy czynnik pierwszy jest maly.

Weryfikacja rozkladow:
- 84: 84/2=42, 42/2=21, 21/3=7, 7 jest pierwszy -> [2,2,3,7], max=7
- 97: 97 jest pierwszy (sprawdzone do sqrt(97)~9.8) -> [97], max=97
- 150: 150/2=75, 75/3=25, 25/5=5, 5/5=1 -> [2,3,5,5], max=5
- 231: 231/3=77, 77/7=11, 11 jest pierwszy -> [3,7,11], max=11
- 128: 128=2^7 -> [2,2,2,2,2,2,2], max=2
- 63: 63/3=21, 21/3=7, 7 jest pierwszy -> [3,3,7], max=7
- 500: 500/2=250, 250/2=125, 125/5=25, 25/5=5, 5/5=1 -> [2,2,5,5,5], max=5
- 1001: 1001/7=143, 143/11=13, 13 jest pierwszy -> [7,11,13], max=13
- 256: 256=2^8 -> [2,2,2,2,2,2,2,2], max=2
